using namespace prodeus;
struct FieldLease {Root owner;Field field=nullptr;int kind=0;double before=0,last=0;};
struct ArrayLease {Root owner;size_t index=0;int32_t before=0,last=0;};
struct Context {Object player=nullptr,controller=nullptr,nav=nullptr;int kind=1;std::string identity="menu";};
struct Backend {
    Context context;Root playerRoot,controllerRoot,navRoot;std::array<bool,13> wanted{},active{};std::array<double,13> values{};
    std::vector<FieldLease> jumps,clips;std::vector<ArrayLease> ammo;
    bool timeOwned=false;double timeBefore=1,timeLast=1;
    bool mouse=false,mouseVisible=false,inputEnabled=false;int mouseLock=0;Root mouseInput;
    NSString *failure=nil;NSTimer *retry=nil;
};
Backend& state(){static Backend *b=new Backend;return *b;}
prodeus::Class game(const char *name){return klass("Assembly-CSharp.dll","",name);}
Object singleton(const char *name){prodeus::Class c=game(name);Field f=field(c,"instance");if(!f || !(api.fieldFlags(f)&0x10))return nullptr;Object value=nullptr;api.staticRead(f,&value);return value && alive(value) ? value : nullptr;}
Object invoke(prodeus::Class c,const char *name,Object target,const std::vector<double>& args={}){Method m=method(c,name,(int)args.size());if(!m)throw std::runtime_error(std::string("Ursprüngliche Methode fehlt: ")+name);uint32_t flags=0;return numericCall(m,(api.methodFlags(m,&flags)&0x10)?nullptr:target,args);}
double numericField(Object object,Field f){if(!object || !f)throw std::runtime_error("Ursprüngliches Wertefeld fehlt.");int k=api.typeKind(api.fieldType(f));if(k==2){bool v=false;api.fieldRead(object,f,&v);return v;}if(k==8){int32_t v=0;api.fieldRead(object,f,&v);return v;}if(k==12){float v=0;api.fieldRead(object,f,&v);return v;}throw std::runtime_error("Ursprünglicher Feldtyp stimmt nicht überein.");}
void writeField(Object object,Field f,double value){int k=api.typeKind(api.fieldType(f));if(k==2){bool v=value!=0;api.fieldWrite(object,f,&v);}else if(k==8){int32_t v=(int32_t)value;api.fieldWrite(object,f,&v);}else if(k==12){float v=(float)value;api.fieldWrite(object,f,&v);}else throw std::runtime_error("Ursprünglicher Feldtyp stimmt nicht überein.");}
bool staticBool(prodeus::Class c,const char *name){Field f=field(c,name);if(!f || !(api.fieldFlags(f)&0x10) || api.typeKind(api.fieldType(f))!=2)throw std::runtime_error("Einzelspieler-Prüffeld fehlt.");bool v=false;api.staticRead(f,&v);return v;}
bool solo(){prodeus::Class info=game("GameInfo");Method m=method(info,"get_IsMultiplayer",0);uint32_t flags=0;if(!m || !(api.methodFlags(m,&flags)&0x10))throw std::runtime_error("Einzelspieler-Prüfung nicht verfügbar.");bool multiplayer=number(call(m,nullptr))!=0;bool room=number(invoke(game("NetworkManager"),"get_InRoom",singleton("NetworkManager")))!=0;bool offline=number(invoke(game("NetworkManager"),"get_OfflineMode",singleton("NetworkManager")))!=0;if((multiplayer || room) && !offline)return false;for(const char *f:{"isCoopMP","isVersusMP","isSoloVersusMP","isTeamVersusMP","editorMode"})if(staticBool(info,f))return false;return true;}
Context capture(){Context c;if(!solo()){c.kind=0;c.identity="multiplayer";return c;}c.controller=singleton("PlayerControllerFirstPerson");c.player=singleton("PlayerEntity");c.nav=singleton("PlayerNavFirstPerson");if(!c.controller || !c.player || !c.nav)return c;if(reference(c.controller,"playerEntity")!=c.player || reference(c.player,"playerController")!=c.controller || reference(c.controller,"playerNav")!=c.nav || !boolean(c.player,"alive"))return c;std::ostringstream id;id<<api.domainGet()<<'/'<<c.player<<'/'<<c.controller<<'/'<<c.nav;c.identity=id.str();c.kind=2;return c;}
void restoreFields(std::vector<FieldLease>& leases){for(auto& l:leases)if(Object owner=l.owner.get())if(alive(owner) && numericField(owner,l.field)==l.last)writeField(owner,l.field,l.before);leases.clear();}
void leaseField(Object owner,const char *name,double value,std::vector<FieldLease>& leases){Field f=field(api.objectClass(owner),name);auto entry=std::find_if(leases.begin(),leases.end(),[&](const FieldLease& l){return l.owner.get()==owner && l.field==f;});if(entry==leases.end()){FieldLease l;l.owner.reset(owner,true);l.field=f;l.before=numericField(owner,f);l.last=l.before;leases.push_back(std::move(l));entry=std::prev(leases.end());}double now=numericField(owner,f);if(now!=value)writeField(owner,f,value);entry->last=value;}
int32_t *arraySlot(Object array,size_t index){if(!array || index>=api.arrayLength(array) || api.arrayLength(array)>512)throw std::runtime_error("Ungültiges ursprüngliches Munitionsfeld.");prodeus::Class element=api.elementClass(api.objectClass(array));uint32_t align=0;if(!element || typeName(api.classType(element))!="System.Int32" || api.valueSize(element,&align)!=4)throw std::runtime_error("Ursprüngliche Munitionsliste hat einen anderen Elementtyp.");return (int32_t *)((uint8_t *)array+api.arrayHeader())+index;}
void leaseSlot(Object array,size_t index,int32_t value,std::vector<ArrayLease>& leases){int32_t *p=arraySlot(array,index);auto entry=std::find_if(leases.begin(),leases.end(),[&](const ArrayLease& l){return l.owner.get()==array && l.index==index;});if(entry==leases.end()){ArrayLease l;l.owner.reset(array,true);l.index=index;l.before=*p;l.last=*p;leases.push_back(std::move(l));entry=std::prev(leases.end());}if(*p!=value)*p=value;entry->last=value;}
// The original SelectedWeaponClip reads the live FPWStateMachine, not the
// controller ammoClip[] loadout cache. Resolve only the selected owned instance.
Object selectedWeapon(const Context& c){
    if(!c.controller || !c.player)return nullptr;
    int index=(int)numericField(c.controller,field(api.objectClass(c.controller),"currentWeapon"));
    Object array=reference(c.controller,"fpwInstances");
    if(index<0 || !array || api.arrayLength(array)>512 || (size_t)index>=api.arrayLength(array))return nullptr;
    prodeus::Class element=api.elementClass(api.objectClass(array));
    if(!element || api.valueType(element))throw std::runtime_error("Ursprüngliche Waffenliste hat einen anderen Elementtyp.");
    Object weapon=nullptr;memcpy(&weapon,(uint8_t *)array+api.arrayHeader()+(size_t)index*sizeof(Object),sizeof(Object));
    if(!weapon || !alive(weapon))return nullptr;
    prodeus::Class expected=game("FPWStateMachine");bool typeMatches=false;
    for(prodeus::Class type=api.objectClass(weapon);type;type=api.parent(type))if(type==expected){typeMatches=true;break;}
    if(!typeMatches || reference(weapon,"player")!=c.controller || reference(weapon,"playerEntity")!=c.player
       || numericField(weapon,field(api.objectClass(weapon),"weaponIndex"))!=index)return nullptr;
    return weapon;
}
void restoreArrays(std::vector<ArrayLease>& leases){for(auto& l:leases)if(Object owner=l.owner.get()){int32_t *p=arraySlot(owner,l.index);if(*p==l.last)*p=l.before;}leases.clear();}
prodeus::Class timeClass(){return klass("UnityEngine.CoreModule.dll","UnityEngine","Time");}
double timeScale(){return number(invoke(timeClass(),"get_timeScale",nullptr));}
void setTime(double value){invoke(timeClass(),"set_timeScale",nullptr,{value});}
bool paused(){return number(invoke(game("GameInfo"),"get_GamePaused",singleton("GameInfo")))!=0;}
void release(){Backend& b=state();restoreFields(b.jumps);restoreArrays(b.ammo);restoreFields(b.clips);if(b.timeOwned && std::fabs(timeScale()-b.timeLast)<.0001)setTime(b.timeBefore);b.timeOwned=false;b.active.fill(false);}
void refresh(){Backend& b=state();Context next=capture();if(next.identity!=b.context.identity){release();b.wanted.fill(false);}b.context=std::move(next);if(b.playerRoot.get()!=b.context.player)b.playerRoot.reset(b.context.player,true);if(b.controllerRoot.get()!=b.context.controller)b.controllerRoot.reset(b.context.controller,true);if(b.navRoot.get()!=b.context.nav)b.navRoot.reset(b.context.nav,true);if(b.context.kind!=2){release();b.wanted.fill(false);}}
bool isToggle(NSInteger f){return f==0 || f==1 || f==2 || f==10 || f==11 || f==12;}
void apply(NSInteger feature){Backend& b=state();Context& c=b.context;b.active[feature]=false;if(!b.wanted[feature]){if(feature==2)restoreFields(b.jumps);if(feature==10)restoreArrays(b.ammo);if(feature==11)restoreFields(b.clips);if(feature==12 && b.timeOwned){if(std::fabs(timeScale()-b.timeLast)<.0001)setTime(b.timeBefore);b.timeOwned=false;}return;}if(c.kind!=2)return;
 if(feature==0 || feature==1){const char *f=feature==0?"health":"armor",*setter=feature==0?"SetHealth":"SetArmor";Field member=field(api.objectClass(c.player),f);double before=numericField(c.player,member);double desired=std::max(200.0,before);if(before<desired)invoke(api.objectClass(c.player),setter,c.player,{desired});b.active[feature]=numericField(c.player,member)>=200;}
 else if(feature==2){leaseField(c.controller,"haveDoubleJump",1,b.jumps);leaseField(c.nav,"canDoubleJump",1,b.jumps);leaseField(c.nav,"jumpCoolDownTimer",0,b.jumps);b.active[feature]=boolean(c.nav,"canDoubleJump") && boolean(c.controller,"haveDoubleJump");}
 else if(feature==10){Object a=reference(c.controller,"ammo");if(!a)return;bool ok=true;for(const char *name:{"bullets","shells","rockets","cells","chaos"}){Field f=field(game("AmmoType"),name);if(!f)throw std::runtime_error("Ursprünglicher Munitionstyp fehlt.");int32_t i=-1;api.staticRead(f,&i);if(i<0)throw std::runtime_error("Ungültiger ursprünglicher Munitionstyp.");int max=(int)number(invoke(api.objectClass(c.controller),"GetMaxAmmo",c.controller,{(double)i}));if(max>0){int32_t *p=arraySlot(a,(size_t)i);bool changed=*p<max;leaseSlot(a,(size_t)i,std::max(*p,max),b.ammo);if(changed)boolean(c.controller,"updateHud",true);ok=ok && *arraySlot(a,(size_t)i)>=max;}}b.active[feature]=ok;}
 else if(feature==11){Object weapon=selectedWeapon(c);if(!b.clips.empty() && b.clips.front().owner.get()!=weapon)restoreFields(b.clips);if(!weapon)return;Field size=field(api.objectClass(weapon),"clipSize"),clip=field(api.objectClass(weapon),"ammoClip");int max=(int)numericField(weapon,size);if(max<=0 || max>10000)return;bool changed=numericField(weapon,clip)!=max;leaseField(weapon,"ammoClip",max,b.clips);if(changed)boolean(c.controller,"updateHud",true);b.active[feature]=numericField(weapon,clip)==max;}
 else if(feature==12){if(paused())return;double current=timeScale();if(!b.timeOwned){if(current<=0)return;b.timeBefore=current;b.timeOwned=true;}double desired=b.values[feature];if(std::fabs(current-desired)>.00001)setTime(desired);b.timeLast=desired;b.active[feature]=std::fabs(timeScale()-desired)<.00001;}
}
void mouseTick(){Backend& b=state();if(!b.mouse)return;if(!alive(b.mouseInput.get())){b.mouse=false;b.mouseInput.reset();return;}prodeus::Class cursor=klass("UnityEngine.CoreModule.dll","UnityEngine","Cursor");if(number(invoke(game("InputManager"),"get_GameInputEnabled",b.mouseInput.get()))!=0)invoke(game("InputManager"),"set_GameInputEnabled",b.mouseInput.get(),{0});if(number(invoke(cursor,"get_lockState",nullptr))!=0)invoke(cursor,"set_lockState",nullptr,{0});if(number(invoke(cursor,"get_visible",nullptr))!=1)invoke(cursor,"set_visible",nullptr,{1});}
void tick(){Backend& b=state();if(!PRInFrame())return;if(!b.mouse && std::none_of(b.wanted.begin(),b.wanted.end(),[](bool x){return x;}) && b.jumps.empty() && b.ammo.empty() && b.clips.empty() && !b.timeOwned)return;try{refresh();mouseTick();if(b.context.kind==2)for(NSInteger i=0;i<13;i++)if(isToggle(i))apply(i);b.failure=nil;}catch(const std::exception& e){b.failure=@(e.what());b.wanted.fill(false);try{release();}catch(...){}b.active.fill(false);}}
NSDictionary *failed(NSString *note){return @{ @"available":@NO,@"active":@NO,@"note":note };}
}
void PRStartBackend(){Backend& b=state();PRSetFrameHandler(^{tick();});if(!b.retry){b.retry=[NSTimer timerWithTimeInterval:.5 repeats:YES block:^(NSTimer *timer){(void)timer;PREnsureLoop();}];[NSRunLoop.mainRunLoop addTimer:b.retry forMode:NSRunLoopCommonModes];}PREnsureLoop();}
NSDictionary *PRInspect(){if(!PRInFrame())return @{ @"kind":@0,@"identity":@"off-thread",@"note":@"Kein nativer Unity-Rückruf." };try{refresh();Backend& b=state();return @{ @"kind":@(b.context.kind),@"identity":@(b.context.identity.c_str()),@"note":b.failure ?: (b.context.kind==2?@"Lokaler Einzelspieler bestätigt.":b.context.kind==0?@"Nur im Einzelspieler verfügbar.":@"Warte auf einen lebenden Einzelspieler.") };}catch(const std::exception& e){return @{ @"kind":@0,@"identity":@"binding-error",@"note":@(e.what()) };}}
NSDictionary *PREffect(NSInteger f,BOOL wanted,double value){if(!PRInFrame() || f<0 || f>=13)return failed(@"Ungültige native Zustellung.");try{refresh();Backend& b=state();bool available=b.context.kind==2;if(isToggle(f)){if(f==12 && (!std::isfinite(value) || value<.1 || value>3))return failed(@"Spieltempo muss zwischen 0,1 und 3 liegen.");bool next=wanted && available;bool changed=b.wanted[f]!=next || (next && b.values[f]!=value);b.wanted[f]=next;b.values[f]=value;if(changed)apply(f);}return @{ @"available":@(available),@"active":@(isToggle(f) && b.active[f]),@"note":available?(b.active[f]?@"Native Wirkung zurückgelesen.":isToggle(f)?(wanted?@"Warte auf einen geeigneten Spielzustand.":@"Aus."):@"Bereit für die einmalige Vergabe."):@"Nur im gültigen Einzelspieler verfügbar." };}catch(const std::exception& e){return failed(@(e.what()));}}
NSString *PROneShot(NSInteger f,double value){(void)value;if(!PRInFrame() || f<3 || f>9)return @"Keine gültige einmalige Aktion.";try{refresh();Context& c=state().context;if(c.kind!=2)return @"Spielzustand gewechselt; Aktion verworfen.";const char *flag=nullptr;prodeus::Class type=api.objectClass(c.controller);if(f<=6){static const char *methods[]={"GiveKeyRed","GiveKeyGreen","GiveKeyBlue","GiveKeyYellow"};static const char *flags[]={"haveRedKey","haveGreenKey","haveBlueKey","haveYellowKey"};flag=flags[f-3];invoke(type,methods[f-3],c.controller);}else if(f==7){flag="haveAutoMap";Field enumField=field(game("MapItem"),"automap");int32_t item=0;if(!enumField)throw std::runtime_error("Originaler Kartenwert fehlt.");api.staticRead(enumField,&item);invoke(type,"GiveMapItem",c.controller,{(double)item});}else{flag=f==8?"haveDoubleJump":"haveDash";Field enumField=field(game("UpgradeItem"),f==8?"doubleJump":"dash");int32_t item=0;if(!enumField)throw std::runtime_error("Originaler Verbesserungswert fehlt.");api.staticRead(enumField,&item);invoke(type,"GiveUpgradeItem",c.controller,{(double)item});}bool confirmed=boolean(c.controller,flag);if(confirmed && f==8){Field granted=field(api.objectClass(c.controller),"haveDoubleJump");for(auto& lease:state().jumps)if(lease.owner.get()==c.controller && lease.field==granted)lease.before=1;}return confirmed?@"Einmalig vergeben und zurückgelesen.":@"Vergabe vom Spiel noch nicht bestätigt.";}catch(const std::exception& e){return [NSString stringWithFormat:@"Vergabe nicht bestätigt: %s",e.what()];}}
void PRRelease(){if(!PRInFrame())return;try{state().wanted.fill(false);release();}catch(const std::exception& e){state().failure=@(e.what());state().active.fill(false);}}
BOOL PRMouse(BOOL wanted){if(!PRInFrame())return NO;try{Backend& b=state();prodeus::Class cursor=klass("UnityEngine.CoreModule.dll","UnityEngine","Cursor");auto get=[&](const char *name){return number(invoke(cursor,name,nullptr));};if(!wanted){if(b.mouse){if(number(invoke(game("InputManager"),"get_GameInputEnabled",b.mouseInput.get()))==0)invoke(game("InputManager"),"set_GameInputEnabled",b.mouseInput.get(),{b.inputEnabled?1.0:0.0});if(get("get_lockState")==0)invoke(cursor,"set_lockState",nullptr,{(double)b.mouseLock});if(get("get_visible")==1)invoke(cursor,"set_visible",nullptr,{b.mouseVisible?1.0:0.0});}b.mouse=false;b.mouseInput.reset();return NO;}if(!b.mouse){Object input=singleton("InputManager");if(!input)return NO;b.mouseInput.reset(input,true);b.mouseVisible=get("get_visible")!=0;b.mouseLock=(int)get("get_lockState");b.inputEnabled=number(invoke(game("InputManager"),"get_GameInputEnabled",input))!=0;b.mouse=true;}mouseTick();return get("get_visible")==1 && get("get_lockState")==0 && number(invoke(game("InputManager"),"get_GameInputEnabled",b.mouseInput.get()))==0;}catch(const std::exception& e){state().failure=@(e.what());return NO;}}
NSDictionary *PRValues(){if(!PRInFrame())return @{};try{refresh();Context& c=state().context;NSMutableDictionary *v=[@{ @"kind":@(c.kind),@"identity":@(c.identity.c_str()),@"loop":PRLoopDiagnostics() } mutableCopy];NSMutableDictionary *session=[NSMutableDictionary new];try{for(const char *f:{"inRoom","isCoopMP","isVersusMP","isSoloVersusMP","isTeamVersusMP","editorMode"})session[@(f)]=@(staticBool(game("GameInfo"),f));session[@"IsMultiplayer"]=@(number(invoke(game("GameInfo"),"get_IsMultiplayer",singleton("GameInfo")))!=0);session[@"OfflineMode"]=@(number(invoke(game("NetworkManager"),"get_OfflineMode",singleton("NetworkManager")))!=0);session[@"NetworkInRoom"]=@(number(invoke(game("NetworkManager"),"get_InRoom",singleton("NetworkManager")))!=0);}catch(const std::exception& e){session[@"error"]=@(e.what());}v[@"session"]=session;if(c.kind==2){for(const char *f:{"health","armor"})v[@(f)]=@(numericField(c.player,field(api.objectClass(c.player),f)));for(const char *f:{"haveRedKey","haveGreenKey","haveBlueKey","haveYellowKey","haveAutoMap","haveDoubleJump","haveDash"})v[@(f)]=@(boolean(c.controller,f));v[@"canDoubleJump"]=@(boolean(c.nav,"canDoubleJump"));v[@"timeScale"]=@(timeScale());v[@"currentWeapon"]=@(numericField(c.controller,field(api.objectClass(c.controller),"currentWeapon")));if(Object weapon=selectedWeapon(c)){v[@"liveClip"]=@(numericField(weapon,field(api.objectClass(weapon),"ammoClip")));v[@"liveClipSize"]=@(numericField(weapon,field(api.objectClass(weapon),"clipSize")));}Object savedClips=reference(c.controller,"ammoClip");if(savedClips && api.arrayLength(savedClips)<512){NSMutableArray *cached=[NSMutableArray new];for(size_t i=0;i<api.arrayLength(savedClips);i++)[cached addObject:@(*arraySlot(savedClips,i))];v[@"loadoutClipCache"]=cached;}v[@"SelectedWeaponAmmo"]=@(number(invoke(api.objectClass(c.controller),"SelectedWeaponAmmo",c.controller)));v[@"SelectedWeaponClip"]=@(number(invoke(api.objectClass(c.controller),"SelectedWeaponClip",c.controller)));v[@"SelectedWeaponClipSize"]=@(number(invoke(api.objectClass(c.controller),"SelectedWeaponClipSize",c.controller)));}return v;}catch(const std::exception& e){return @{ @"error":@(e.what()) };}}
